def transform(grid):
    # The task takes a grid and compresses 3x3 blocks into single cells
    # Each cell in the output is the dominant non-5 color of the corresponding 3x3 block
    # 5 is treated as background

    R, C = len(grid), len(grid[0])
    H_out, W_out = R // 3, C // 3

    output = []
    for r in range(0, R, 3):
        row_output = []
        for c in range(0, C, 3):
            # Count colors in the 3x3 block
            counts = {}
            for i in range(3):
                for j in range(3):
                    val = grid[r + i][c + j]
                    counts[val] = counts.get(val, 0) + 1

            # Find dominant non-5 color
            best = 0
            best_count = 0
            for color, count in counts.items():
                if color != 5 and count > best_count:
                    best = color
                    best_count = count

            row_output.append(best)
        output.append(row_output)

    return output
